import json
baseline = json.load(open('baseline-packages.json'))
after = json.load(open('after-cpm-packages.json'))

def pkg_map(data):
    result = {}
    for p in data['projects']:
        name = p['path'].split('/')[-1]
        for f in p['frameworks']:
            for pkg in f['topLevelPackages']:
                key = (name, f['framework'], pkg['id'])
                result[key] = pkg['resolvedVersion']
    return result

b = pkg_map(baseline)
a = pkg_map(after)

changes = []
unchanged = []
for key in sorted(set(list(b.keys()) + list(a.keys()))):
    bv = b.get(key, 'N/A')
    av = a.get(key, 'N/A')
    proj, fw, pkg = key
    if bv != av:
        changes.append((proj, fw, pkg, bv, av))
    else:
        unchanged.append((proj, fw, pkg, bv))

print('=== CHANGES ===')
for c in changes:
    print(f'{c[0]} ({c[1]}): {c[2]} {c[3]} -> {c[4]}')
print()
print(f'=== UNCHANGED: {len(unchanged)} packages ===')
for u in unchanged:
    print(f'{u[0]} ({u[1]}): {u[2]} {u[3]}')
"

